/**
 ******************************************************************************
 * @file    test_output_chain.c
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tom's sound output subsystem (best-ui), with an AI coding assistant;
 *          Brendon (integrator) added the FxResumeTests group (30 Oct 2026, with an AI coding assistant).
 * @brief   Host tests of the output chain: the runner of test_output_chain.
 *
 * What it covers: the three pure modules between a recording and the
 * speakers. Pure host tests: no RTOS, no HAL, no board.
 *
 *   recording (32 kHz) -> RateAdapter2to3 -> AudioEffects  (FxRender: made
 *                                                           into a file by
 *                                                           FxRenderTask)
 *   file or recording  -> TomTask: RateAdapter2to3 (32 kHz only) -> Crossover
 *                                  -> speaker trim -> I2S3
 *
 * Test groups (one file each):
 *   RateAdapterTests  (test_rate_adapter.c)  the 2:3 upsampler gives exactly
 *                                            the old TomTask samples; how
 *                                            much of a block fits in a half
 *   FxRenderTests     (test_fx_render.c)     an effect file is sample for
 *                                            sample what the old live chain
 *                                            would play with today's effects
 *                                            (Echo now 240 ms); pitch
 *                                            presets; chunking; 48 kHz
 *                                            sources; lengths; errors; one
 *                                            renderer for many files
 *   FxResumeTests     (test_fx_resume.c)     a file made again from the
 *                                            middle (pre-roll + carry) is
 *                                            the one-go file from there on
 *                                            (Echo and Reverb within a few
 *                                            units), every effect, both rates
 *   CrossoverTests    (test_crossover.c)     the 1600 Hz LR4 crossover: its
 *                                            numbers, the gains of both
 *                                            sides, the flat sum, the 10 Hz
 *                                            high-pass, the silence bypass,
 *                                            rounding, clipping and channel
 *                                            order
 * The copy of the old live chain's upsampler and effect loop that the tests
 * compare against: live_chain_oracle.c.
 ******************************************************************************
 */
#include "unity_fixture.h"

TEST_GROUP(RateAdapterTests);
TEST_GROUP(FxRenderTests);
TEST_GROUP(FxResumeTests);
TEST_GROUP(CrossoverTests);

/** Run every group of the output-chain test executable. */
static void RunAllTests(void)
{
    RUN_TEST_GROUP(RateAdapterTests);
    RUN_TEST_GROUP(FxRenderTests);
    RUN_TEST_GROUP(FxResumeTests);
    RUN_TEST_GROUP(CrossoverTests);
}

/** Host test entry point used by CTest. */
int main(int argc, const char *argv[])
{
    return UnityMain(argc, argv, RunAllTests);
}
